  // Scope stats row
  const stats = [
    { val: "1,001", label: "Use Cases" },
    { val: "11", label: "Industries" },
    { val: "6", label: "Agent Types" },
  ];
  stats.forEach((s, i) => {
    const sx = 0.6 + i * 2.2;
    slide.addText(s.val, {
      x: sx, y: 3.25, w: 2.0, h: 0.65,
      fontSize: 38, fontFace: HEADER_FONT, color: C.white,
      bold: true, align: "left", valign: "bottom", margin: 0
    });
    slide.addText(s.label, {
      x: sx, y: 3.88, w: 2.0, h: 0.35,
      fontSize: 12, fontFace: BODY_FONT, color: C.iceBlue,
      align: "left", valign: "top", margin: 0
    });
  });

  // Source & growth note
  slide.addText("Source: Google Cloud Blog — 10× growth from 101 to 1,001 use cases in 18 months  |  Updated October 2025", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.3,
    fontSize: 10, fontFace: BODY_FONT, color: C.mutedText,
    align: "left", valign: "middle", margin: 0
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.545, w: 10, h: 0.08,
    fill: { color: C.accent }, line: { color: C.accent, width: 0 }
  });
}

// ================================================================
// SLIDE 2 — GROWTH TRAJECTORY 101 → 1,001
// ================================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  // Title
  slide.addText("From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months", {
