  });
  slide.addText("+400 New Entries Added", {
    x: 4.2, y: 2.35, w: 1.6, h: 0.5,
    fontSize: 10, fontFace: BODY_FONT, color: C.accentOrange,
    bold: true, align: "center", valign: "bottom", margin: 0
  });

  // Timeline node 2 — October 2025
  slide.addShape(pres.shapes.OVAL, {
    x: 9.2 - 0.22, y: 3.0 - 0.22, w: 0.44, h: 0.44,
