  });
  // Card below
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.9, y: 3.25, w: 1.8, h: 1.4,
    fill: { color: C.accentLight }, line: { color: C.accent, width: 0.75 },
    shadow: cardShadow()
  });
  slide.addText("1,001", {
    x: 7.9, y: 3.35, w: 1.8, h: 0.65,
    fontSize: 40, fontFace: HEADER_FONT, color: C.accent,
    bold: true, align: "center", valign: "middle", margin: 0
  });
  slide.addText("Use Cases\nOctober 2025", {
    x: 7.9, y: 4.0, w: 1.8, h: 0.55,
    fontSize: 10, fontFace: BODY_FONT, color: C.navy,
    align: "center", valign: "top", margin: 0
  });

  // Growth callout arrow
  slide.addText("10×", {
    x: 4.1, y: 3.35, w: 1.4, h: 0.7,
