  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }, line: { color: C.accent, width: 0 }
  });

  // Title
  slide.addText("Takeaways: Where to Start and What to Expect from Enterprise Gen AI", {
    x: 0.5, y: 0.35, w: 9.0, h: 0.7,
