  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  lightGray: "F5F7FA",
  darkText: "1E2761",
  mutedText: "64748B",
  accent: "4285F4",   // Google blue
  accentLight: "E8F0FE",
  accentGreen: "0D9488",
  accentOrange: "F59E0B",
  gridLine: "E2E8F0",
  tableHead: "1E2761",
  tableAlt: "F1F5F9",
};

// Fonts
const HEADER_FONT = "Arial Black";
const BODY_FONT = "Arial";
const monoFont = "Consolas";

// ---- Helper: card shadow factory ----
const cardShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 2, angle: 135, opacity: 0.10 });

// ================================================================
// SLIDE 1 — TITLE COVER
// ================================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accent }, line: { color: C.accent, width: 0 }
  });

  // Main title
  slide.addText("1,001 Real-World Gen AI Use Cases", {
    x: 0.6, y: 1.5, w: 8.8, h: 0.9,
    fontSize: 36, fontFace: HEADER_FONT, color: C.white,
    bold: true, align: "left", valign: "bottom", margin: 0
  });
  slide.addText("from Google Cloud Customers", {
    x: 0.6, y: 2.35, w: 8.8, h: 0.55,
    fontSize: 28, fontFace: HEADER_FONT, color: C.iceBlue,
    bold: false, align: "left", valign: "top", margin: 0
  });

  // Thin divider line
  slide.addShape(pres.shapes.LINE, {
    x: 0.6, y: 3.05, w: 3.0, h: 0,
    line: { color: C.accent, width: 2 }
  });

  // Scope stats row
  const stats = [
    { val: "1,001", label: "Use Cases" },
    { val: "11", label: "Industries" },
    { val: "6", label: "Agent Types" },
  ];
  stats.forEach((s, i) => {
    const sx = 0.6 + i * 2.2;
    slide.addText(s.val, {
      x: sx, y: 3.25, w: 2.0, h: 0.65,
      fontSize: 38, fontFace: HEADER_FONT, color: C.white,
      bold: true, align: "left", valign: "bottom", margin: 0
    });
    slide.addText(s.label, {
      x: sx, y: 3.88, w: 2.0, h: 0.35,
      fontSize: 12, fontFace: BODY_FONT, color: C.iceBlue,
      align: "left", valign: "top", margin: 0
    });
  });

  // Source & growth note
  slide.addText("Source: Google Cloud Blog — 10× growth from 101 to 1,001 use cases in 18 months  |  Updated October 2025", {
    x: 0.6, y: 5.1, w: 8.8, h: 0.3,
    fontSize: 10, fontFace: BODY_FONT, color: C.mutedText,
    align: "left", valign: "middle", margin: 0
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.545, w: 10, h: 0.08,
    fill: { color: C.accent }, line: { color: C.accent, width: 0 }
  });
}

// ================================================================
// SLIDE 2 — GROWTH TRAJECTORY 101 → 1,001
// ================================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  // Title
  slide.addText("From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months", {
    x: 0.5, y: 0.35, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: HEADER_FONT, color: C.navy,
    bold: true, align: "left", valign: "middle", margin: 0
  });

  // Subtitle
  slide.addText("April 2024 — Cloud Next 24 — October 2025", {
    x: 0.5, y: 1.0, w: 9.0, h: 0.35,
    fontSize: 14, fontFace: BODY_FONT, color: C.mutedText,
    align: "left", valign: "top", margin: 0
  });

  // ---- Timeline backbone ----
  // Horizontal line
  slide.addShape(pres.shapes.LINE, {
    x: 0.8, y: 3.0, w: 8.4, h: 0,
