  });
  slide.addText("OCT 2025", {
    x: 8.4, y: 2.35, w: 1.6, h: 0.3,
    fontSize: 11, fontFace: BODY_FONT, color: C.accent,
    bold: true, align: "center", valign: "bottom", margin: 0, charSpacing: 2
  });
  // Card below
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.9, y: 3.25, w: 1.8, h: 1.4,
    fill: { color: C.accentLight }, line: { color: C.accent, width: 0.75 },
    shadow: cardShadow()
  });
  slide.addText("1,001", {
    x: 7.9, y: 3.35, w: 1.8, h: 0.65,
    fontSize: 40, fontFace: HEADER_FONT, color: C.accent,
    bold: true, align: "center", valign: "middle", margin: 0
  });
  slide.addText("Use Cases\nOctober 2025", {
    x: 7.9, y: 4.0, w: 1.8, h: 0.55,
    fontSize: 10, fontFace: BODY_FONT, color: C.navy,
    align: "center", valign: "top", margin: 0
  });

  // Growth callout arrow
  slide.addText("10×", {
    x: 4.1, y: 3.35, w: 1.4, h: 0.7,
    fontSize: 32, fontFace: HEADER_FONT, color: C.accentGreen,
    bold: true, align: "center", valign: "middle", margin: 0
  });
  slide.addText("growth in 18 months", {
    x: 3.7, y: 3.95, w: 2.2, h: 0.3,
    fontSize: 10, fontFace: BODY_FONT, color: C.mutedText,
    align: "center", valign: "top", margin: 0
  });

  // Bottom note
  slide.addText("\"This still only scratches the surface of what is becoming possible.\" — Google Cloud Blog, October 2025", {
    x: 0.5, y: 5.1, w: 9.0, h: 0.3,
    fontSize: 10, fontFace: BODY_FONT, color: C.mutedText,
    italic: true, align: "left", valign: "middle", margin: 0
  });
}

// ================================================================
// SLIDE 3 — INDUSTRY & AGENT TAXONOMY MATRIX
// ================================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  // Title
  slide.addText("11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.6,
    fontSize: 22, fontFace: HEADER_FONT, color: C.navy,
    bold: true, align: "left", valign: "middle", margin: 0
  });

  // Subtitle
  slide.addText("The 1,001 use cases are organized across 11 industry verticals and 6 distinct agent archetypes", {
    x: 0.5, y: 0.88, w: 9.0, h: 0.3,
    fontSize: 12, fontFace: BODY_FONT, color: C.mutedText,
    align: "left", valign: "top", margin: 0
  });

  // Column widths: industry col + 6 equal agent cols
  const tableX = 0.5;
  const tableY = 1.3;
  const indColW = 2.2;
  const agentColW = (9.0 - 2.2 - 0.1) / 6; // ~1.12
  const rowH = 0.31;

  // Header row: Industry | Customer | Employee | Creative | Code | Data | Security
  const headers = ["Industry", "Customer", "Employee", "Creative", "Code", "Data", "Security"];

  // Header background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: tableX, y: tableY, w: 9.0, h: rowH + 0.02,
    fill: { color: C.tableHead }, line: { color: C.tableHead, width: 0 }
  });

  headers.forEach((h, i) => {
    const cx = tableX + (i === 0 ? 0 : indColW + (i - 1) * agentColW);
    const cw = i === 0 ? indColW : agentColW;
    slide.addText(h, {
      x: cx + 0.06, y: tableY + 0.02, w: cw - 0.12, h: rowH - 0.04,
      fontSize: 9, fontFace: BODY_FONT, color: C.white,
