    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Business & Prof. Services",
    "Hospitality & Travel",
    "Technology",
    "Telecommunications",
  ];

  industries.forEach((ind, ri) => {
    const ry = tableY + rowH + 0.02 + ri * (rowH + 0.02);
    const bg = ri % 2 === 0 ? C.lightGray : C.white;

    // Row background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: tableX, y: ry, w: 9.0, h: rowH + 0.02,
      fill: { color: bg }, line: { color: C.gridLine, width: 0.5 }
