    { name: "Security", desc: "Threat detection, compliance, fraud" },
  ];
  const pillY = legendY + 0.35;
  agentTypes.forEach((at, i) => {
    const px = 0.5 + i * 1.52;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: px, y: pillY, w: 1.45, h: 0.62,
      fill: { color: C.accentLight }, line: { color: C.accent, width: 0.5 }
    });
    slide.addText(at.name, {
      x: px + 0.08, y: pillY + 0.06, w: 1.3, h: 0.22,
      fontSize: 9, fontFace: BODY_FONT, color: C.accent,
      bold: true, align: "left", valign: "top", margin: 0
    });
    slide.addText(at.desc, {
      x: px + 0.08, y: pillY + 0.27, w: 1.3, h: 0.3,
      fontSize: 7.5, fontFace: BODY_FONT, color: C.mutedText,
      align: "left", valign: "top", margin: 0
    });
  });
}

// ================================================================
// SLIDE 4 — AUTOMOTIVE & LOGISTICS DEEP-DIVE
// ================================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  // Title
  slide.addText("Automotive & Logistics: AI Agents From Cockpit to Curbside", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.55,
    fontSize: 22, fontFace: HEADER_FONT, color: C.navy,
    bold: true, align: "left", valign: "middle", margin: 0
  });

  slide.addText("Representative use cases across Customer, Employee, Code, and Data agent types", {
    x: 0.5, y: 0.85, w: 9.0, h: 0.25,
    fontSize: 11, fontFace: BODY_FONT, color: C.mutedText,
    align: "left", valign: "top", margin: 0
  });

  // Table data
  const tableData = [
    // Header row
    [
      { text: "Agent Type", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "left" } },
      { text: "Organization", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "left" } },
      { text: "Use Case Summary", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "left" } },
      { text: "Key Metric / Detail", options: { bold: true, fill: { color: C.navy }, color: C.white, align: "left" } },
    ],
    // Customer
    [
      { text: "Customer", options: { bold: true, fill: { color: C.accentLight }, color: C.accent } },
      { text: "Mercedes-Benz", options: { fill: { color: C.accentLight } } },
      { text: "MBUX Virtual Assistant powered by Gemini via Vertex AI — natural language in-car conversations", options: { fill: { color: C.accentLight } } },
      { text: "Natural language in-car assistant", options: { fill: { color: C.accentLight }, italic: true } },
    ],
    [
      { text: "Customer", options: { bold: true, fill: { color: C.white } } },
      { text: "LUXGEN (Taiwan EV)", options: { fill: { color: C.white } } },
      { text: "AI agent on LINE messaging platform answers customer questions via Vertex AI", options: { fill: { color: C.white } } },
      { text: "30% human CS workload reduction", options: { fill: { color: C.white }, italic: true, bold: true, color: C.accentGreen } },
    ],
    [
