      { text: "General Motors (OnStar)", options: { fill: { color: C.accentLight } } },
      { text: "Virtual assistant with Google Cloud conversational AI recognizes speaker intent", options: { fill: { color: C.accentLight } } },
      { text: "Improved intent recognition accuracy", options: { fill: { color: C.accentLight }, italic: true } },
    ],
